SELECT d.id AS destination_id, dt.name, dt.short_description, di.image_url FROM destinations d JOIN destination_translations dt ON dt.destination_id = d.id AND dt.language_code = 'ko' LEFT JOIN destination_images di ON di.destination_id = d.id AND di.is_main = 1 WHERE d.region_id IN
#{id}
ORDER BY RAND() LIMIT #{limit}
